/**
 * Statement sentences (spec 8.7). Deterministic templates, never generated by a
 * model. Every branch has a unit test in statements.test.ts.
 */
import { formatQuarter } from './format';
import { metrics } from './metrics';

const AT_LINE = metrics.line.at_line_band;
const STREAK_MIN = metrics.statements.streak_min;
const FLAT = metrics.statements.flat_band;
const DIRECTION_WEEKS = metrics.statements.direction_weeks;

/** "Software job postings" or "Software job postings in the United States". */
export function postingsNoun(shortLabel: string | null, where?: string): string {
  const base = shortLabel && shortLabel !== 'All jobs' ? `${shortLabel} job postings` : 'Job postings';
  return where ? `${base} in ${where}` : base;
}

/** "{noun} are 34% below the line" / "are at the line" / "are 12% above the line". */
export function positionClause(noun: string, index: number): string {
  const d = index - 100;
  if (Math.abs(d) <= AT_LINE) return `${noun} are at the line`;
  return d < 0
    ? `${noun} are ${Math.round(-d)}% below the line`
    : `${noun} are ${Math.round(d)}% above the line`;
}

/** Signed count of consecutive weekly moves ending at the last value. */
export function currentStreak(values: number[]): number {
  let k = 0;
  for (let i = values.length - 1; i > 0; i--) {
    const d = values[i]! - values[i - 1]!;
    if (d > 0 && k >= 0) k += 1;
    else if (d < 0 && k <= 0) k -= 1;
    else break;
  }
  return k;
}

export function changeOver(values: number[], weeks = DIRECTION_WEEKS): number | null {
  if (values.length <= weeks) return null;
  const last = values[values.length - 1]!;
  const prev = values[values.length - 1 - weeks]!;
  return (last / prev - 1) * 100;
}

/** Direction from the 4-week mean series, oldest first (spec 8.7). */
export function directionClause(fourWeekMeans: number[]): string {
  const k = currentStreak(fourWeekMeans);
  if (k >= STREAK_MIN) return `and have risen for ${k} weeks`;
  if (k <= -STREAK_MIN) return `and have fallen for ${-k} weeks`;
  const change = changeOver(fourWeekMeans);
  if (change === null) return '';
  if (change > FLAT) return `and are up ${Math.round(change)}% in three months`;
  if (change < -FLAT) return `and are down ${Math.round(-change)}% in three months`;
  return 'and have been flat for three months';
}

/**
 * Position from the latest weekly reading (what charts show), direction from the
 * four-week average (smoother). Without `latest`, the last four-week value is used.
 */
export function sectorSentence(noun: string, fourWeekMeans: number[], latest?: number): string {
  const last = latest ?? fourWeekMeans[fourWeekMeans.length - 1]!;
  const direction = directionClause(fourWeekMeans);
  return `${positionClause(noun, last)}${direction ? ` ${direction}` : ''}.`;
}

/** "Frontend engineering in France: Cold, 31 of 100. Software job postings are ..." */
export function outlookStatement(
  family: string,
  where: string,
  state: string,
  score: number,
  sectorNoun: string,
  fourWeekMeans: number[],
  latest?: number,
): string {
  return `${family} in ${where}: ${state}, ${Math.round(score)} of 100. ${sectorSentence(sectorNoun, fourWeekMeans, latest)}`;
}

export type Recovery = {
  status: 'above' | 'range' | 'earliest' | 'none';
  q20: string | null;
  q80: string | null;
};

/** Recovery range in words (spec 8.3 step 7). */
export function recoverySentence(r: Recovery): string {
  switch (r.status) {
    case 'above':
      return 'Postings are above the line.';
    case 'range': {
      const a = formatQuarter(r.q20!);
      const b = formatQuarter(r.q80!);
      return a === b
        ? `At the current pace, postings reach the line in ${a}.`
        : `At the current pace, postings reach the line between ${a} and ${b}.`;
    }
    case 'earliest':
      return `At the current pace, the earliest likely return to the line is ${formatQuarter(r.q20!)}. It may take longer than two years.`;
    case 'none':
      return 'At the current pace, postings do not reach the line within two years.';
  }
}

/** Used when the forecast did not beat the naive baseline (spec 8.3 step 5). */
export function notPredictableSentence(change13: number | null): string {
  const base = 'The trend is not predictable enough to project.';
  if (change13 === null) return base;
  const n = Math.round(change13);
  if (n === 0) return `${base} Recent direction: flat over 13 weeks.`;
  return `${base} Recent direction: ${n > 0 ? 'up' : 'down'} ${Math.abs(n)}% in 13 weeks.`;
}

export const FORECAST_CAVEAT = 'This projects recent patterns forward. It cannot foresee shocks.';

/** "Of 31 companies that tied job cuts to AI, 9 have walked them back and 6 are holding." */
export function aftermathStatement(n: number, walkedBack: number, holding: number): string {
  return `Of ${n} companies that tied job cuts to AI, ${walkedBack} have walked them back and ${holding} are holding.`;
}

const BAND_WORDS: Record<string, string> = {
  Calm: 'calm',
  Stretched: 'stretched, not yet strained',
  Strained: 'strained',
};

/** "The AI boom is stretched, not yet strained. 6 of 9 indicators sit above their long-run norm." */
export function pressureStatement(band: 'Calm' | 'Stretched' | 'Strained', above: number, total: number): string {
  return `The AI boom is ${BAND_WORDS[band]}. ${above} of ${total} indicators sit above their long-run norm.`;
}

/** Junior visitors with entry access below 30 (spec 8.1). */
export function entryAccessSentence(juniorShare: number): string {
  return `Few openings accept under two years of experience right now: ${Math.round(juniorShare * 100)}% of postings.`;
}
